const rows = $input.all();
const cfg = {};
for (const it of rows) {
  const k = it.json.setting !== undefined ? it.json.setting : it.json.key;
  if (k === undefined || k === null || String(k).trim() === '') continue;
  cfg[String(k).trim()] = it.json.value;
}
cfg.OWNER_NAME = 'Aditya';
cfg.SENDER_NAME = 'Aditya';
if (String(cfg.GLOBAL_PAUSE || '').trim() !== '') { throw new Error('GLOBAL_PAUSE is set - aborting'); }
return [{ json: cfg }];

const TARGETS = ['D00009', 'D00026', 'D00036'];
const NEW_EMAIL = 'ravisaikrishna@blacksoil.co.in';
const blank = (x) => x === undefined || x === null || String(x).trim() === '';
const out = [];
for (const it of $('Read PIPELINE').all()) {
  const r = it.json;
  if (TARGETS.indexOf(String(r.deal_id).trim()) === -1) continue;
  if (!blank(r.pause)) throw new Error('Row ' + r.deal_id + ' is paused - aborting');
  if (!blank(r.investor_response)) throw new Error('Row ' + r.deal_id + ' already has an investor_response - aborting');
  if (String(r.email || '').trim().toLowerCase() !== NEW_EMAIL) throw new Error('Row ' + r.deal_id + ' email is not the new address - aborting');
  out.push({ json: { deal_id: r.deal_id, startup: r.startup, investor: r.investor, owner: r.owner, email: r.email, cc: r.cc || '', thread_id: '', message_id: '', channel: r.channel, action: 'send', reason: 'resend-initial-new-contact', stage: 'INITIAL' } });
}
if (out.length !== TARGETS.length) { throw new Error('Expected ' + TARGETS.length + ' rows, found ' + out.length + ' - aborting'); }
return out;

const cfg = $('Build CONFIG object').first().json;
const r = $json;
const stage = r.stage;

let st = null;
for (const s of $('Read STARTUPS').all()) { if (String(s.json.startup).trim() === String(r.startup).trim()) { st = s.json; break; } }
let inv = null;
for (const v of $('Read INVESTORS').all()) { if (String(v.json.investor).trim() === String(r.investor).trim()) { inv = v.json; break; } }
if (!st) throw new Error('Startup not found: ' + r.startup);
if (!inv) throw new Error('Investor not found: ' + r.investor);

const isRouting = String(r.channel || '').toUpperCase() === 'ROUTING';
const tid = (stage === 'INITIAL' && isRouting) ? 'INITIAL_ROUTING' : stage;

let tpl = null;
for (const t of $('Read TEMPLATES').all()) { if (String(t.json.template_id).trim() === tid) { tpl = t.json; break; } }
if (!tpl) throw new Error('Template not found for stage ' + tid);

const tokens = {
  '{{InvestorName}}': inv.investor,
  '{{ContactPerson}}': inv.contact_person,
  '{{StartupName}}': st.startup,
  '{{Sector}}': st.sector,
  '{{FundraiseAmount}}': st.raise_inr_cr,
  '{{Revenue}}': st.revenue,
  '{{Highlight1}}': st.highlight_1,
  '{{Highlight2}}': st.highlight_2,
  '{{Highlight3}}': st.highlight_3,
  '{{DeckLink}}': st.deck_link,
  '{{SenderName}}': cfg.SENDER_NAME,
};
const fill = (s) => {
  let out = String(s == null ? '' : s);
  for (const k in tokens) { out = out.split(k).join(String(tokens[k] == null ? '' : tokens[k])); }
  return out;
};
const subject = fill(tpl.subject);
const body0 = fill(tpl.body);
const memoHtml = (st.memo_html == null ? '' : String(st.memo_html));
const body = String(body0).split('{{MemoBody}}').join('%%MEMOBODY_SLOT%%');
if (/\{\{[^}]+\}\}/.test(subject) || /\{\{[^}]+\}\}/.test(body)) {
  throw new Error('Unresolved template token for deal ' + r.deal_id);
}

const ownerNames = { Aditya: "Aditya Mishra", Chaman: "Chaman Yadav", Akansha: "Akansha", Shradha: "Shradha" };
const senderFull = ownerNames[String(cfg.SENDER_NAME).trim()] || cfg.SENDER_NAME;
const logoUrl = "https://drive.google.com/uc?export=view&id=1iLMGooCx6B8bmYJxlYMdNg0YhdSoFAFi";
const bodyHtml0 = String(body).split(String.fromCharCode(10)).join("<br>");
const bodyHtml = bodyHtml0.split('%%MEMOBODY_SLOT%%').join("<div style='height:18px;'></div>" + memoHtml + "<div style='height:18px;'></div>");
const sig = "<br>--<br>" + "<img src='" + logoUrl + "' alt='Sidana Ventures' width='120' style='display:block;margin-bottom:8px;border:0;'>" + "<div style='font-family:Arial,sans-serif;font-size:13px;color:#333333;line-height:1.4;'>" + "<span style='font-weight:bold;color:#1a5fb4;'>" + senderFull + "</span><br>" + "Investor Relations<br>" + "<span style='font-weight:bold;'>SIDANA VENTURES LLP</span><br>" + "424A Tower B3, Spaze iTech Park, Sector 49, Sohna Road<br>" + "Gurgaon, Haryana 122022<br>" + "+91 87965 31802<br>" + "<a href='https://www.sidanaventures.com' style='color:#1a5fb4;'>www.sidanaventures.com</a>" + "</div>";
const html = "<div style='font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.65;color:#222222;max-width:640px;'>" + bodyHtml + "</div>" + sig;

return { json: Object.assign({}, r, {
  to: r.email,
  cc: r.cc || '',
  subject,
  body,
  html,
}) };

const cfg = $('Build CONFIG object').first().json;
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const now = DateTime.now().setZone(tz);
const today = now.toISODate();
const fu1 = parseInt(cfg.FU1_DAYS, 10); const FU1 = isNaN(fu1) ? 2 : fu1;
const resp = $json;
const be = $('Build email').item.json;
return { json: {
  deal_id: be.deal_id,
  deal_shared: 'Yes',
  date_shared: today,
  channel: 'Email',
  thread_id: resp.threadId || '',
  message_id: resp.id || '',
  last_contact: today,
  next_action: 'Follow-up 1',
  next_due: now.plus({ days: FU1 }).toISODate(),
  fu1_done: '',
  fu1_date: '',
  fu2_done: '',
  fu2_date: '',
  fu3_done: '',
  fu3_date: '',
} };
